# -*- coding: utf-8 -*-
# 팟캐스트 1단계 (이 파일 하나로 끝): 새 파일 2개(lib/podcast/podcast.dart · podcast_screens.dart) 만들기
# + 라디오(국내·해외)에 '팟캐스트' 탭 + 재생기·알림창 연결
import base64, os
_NEW = {
    os.path.join('lib', 'podcast', 'podcast.dart'): "",
    os.path.join('lib', 'podcast', 'podcast_screens.dart'): "",
}
for _p, _b in _NEW.items():
    _data = base64.b64decode(_b)
    if os.path.exists(_p) and open(_p, 'rb').read().replace(b'\r\n', b'\n') == _data:
        print('✔', os.path.basename(_p), '(이미 있음)')
        continue
    os.makedirs(os.path.dirname(_p), exist_ok=True)
    open(_p, 'wb').write(_data)
    print('✔', os.path.basename(_p), '새로 만들었어요')
import os, re, sys

P = {
    'pubspec': 'pubspec.yaml',
    'main': os.path.join('lib', 'main.dart'),
    'player': os.path.join('lib', 'providers', 'player_provider.dart'),
    'korea': os.path.join('lib', 'screens', 'radio_korea_screen2.dart'),
    'world': os.path.join('lib', 'screens', 'radio_country_stations_screen.dart'),
}


def fail(m):
    print('❌', m, '— 아무것도 저장하지 않았어요.')
    sys.exit(1)


for f in (os.path.join('lib', 'podcast', 'podcast.dart'), os.path.join('lib', 'podcast', 'podcast_screens.dart')):
    if not os.path.exists(f):
        fail(f'{f} 가 없어요. 먼저 만들어 주세요')

D = {}
for k, p in P.items():
    if not os.path.exists(p):
        fail('파일이 없어요: ' + p)
    raw = open(p, 'rb').read().decode('utf-8')
    D[k] = {'s': raw.replace('\r\n', '\n'), 'crlf': '\r\n' in raw}
    D[k]['orig'] = D[k]['s']


def name(k):
    return os.path.basename(P[k])


def rep(k, label, old, new, done_mark=None):
    s = D[k]['s']
    if (done_mark or new) in s:
        print('✔', name(k), label, '(이미 돼 있음)')
        return
    n = s.count(old)
    if n != 1:
        fail(f'{name(k)} {label} — 찾을 코드를 못 찾았어요 ({n}곳)')
    D[k]['s'] = s.replace(old, new)
    print('✔', name(k), label)


def rep_re(k, label, pat, new, done_mark, count=None):
    s = D[k]['s']
    if done_mark in s and count is None:
        print('✔', name(k), label, '(이미 돼 있음)')
        return
    s2, n = re.subn(pat, new, s)
    if n == 0 and done_mark in s:
        print('✔', name(k), label, '(이미 돼 있음)')
        return
    if n == 0 or (count is not None and n != count):
        fail(f'{name(k)} {label} — 찾을 코드를 못 찾았어요 ({n}곳)')
    D[k]['s'] = s2
    print('✔', name(k), label, f'({n}곳)')


